// test_offload.c - fake host for the OpenMP offload test on MAGIA v4 (1 tile).
//                  Minimal version of HERO2/apps/omp/basic/offload_benchmark/main.c.
//
// The regions are those of src/kernels_omp.c:
//
//   #pragma omp target device(1)                     { asm volatile("nop"); }
//   #pragma omp target device(1) map(to : tmp_1)     { volatile uint32_t local_tmp_1 = tmp_1; }
//   #pragma omp target device(1) map(tofrom : tmp_1, tmp_2) { tmp_1 = tmp_2; }
//
//   PART 1 (device side): generated by the HERO clang + OmpKernelWrapper
//     (kernels_omp.o): for each region a body function ("__wrapped_...") and a
//     wrapper with the single signature  void f(uint64_t argbuf).
//     This file only has to FIND the wrappers (resolve_kernels).
//
//   PART 2 (host side): what libomptarget + the HERO plugin (rtl.cpp) do:
//     allocate buffers in L2, copy data, build argbuf, send START,
//     then read DONE and copy the results back.
//
// With a single tile there is no real host: the fake host queues all commands
// BEFORE the device loop starts and checks the results AFTER STOP.
//
// TODO(RTEMS host): this whole file is the host side simulated on the MAGIA core
// and must be rewritten on the RTEMS host (QEMU); see the TODOs below.

#include <stdint.h>
#include "common/ringbuf.h"
#include "offload_layout.h"
#include "tile.h"              // magia-sdk: printf

typedef void (*kernel_t)(uint64_t);      // wrapper signature (OmpKernelWrapper)

// ===========================================================================
// PART 1 - kernel lookup
// The compiler emits one entry per #pragma omp target (wrapper address + name)
// in the "omp_offloading_entries" section of the device program. The HERO
// plugin does the same with satisfy_requested_symbols (rtl.cpp:106).
//
// TODO(RTEMS host): host and kernels will be separate ELFs and
// __start/__stop_omp_offloading_entries will not exist on the host: read the
// __omp_offloading_* addresses from the MAGIA ELF symbol table (e.g. in the ELF loader).
// ===========================================================================

struct tgt_offload_entry {      // device-side %struct.__tgt_offload_entry (32 bit, 20 bytes)
    void     *addr;             // wrapper address
    char     *name;             // "__omp_offloading_<id>_regions_l<pragma line>"
    uint32_t  size;
    int32_t   flags;
    int32_t   reserved;
};
// Defined by the linker for the "omp_offloading_entries" section
extern struct tgt_offload_entry __start_omp_offloading_entries[];
extern struct tgt_offload_entry __stop_omp_offloading_entries[];

// Regions are identified by the line of their #pragma in src/kernels_omp.c
// (the rest of the name depends on the file). Update these if those lines
// move; the test prints the actual names.
#define KERNEL_NOP_SUFFIX        "_l28"
#define KERNEL_MAP_TO_SUFFIX     "_l32"
#define KERNEL_MAP_TOFROM_SUFFIX "_l36"

static int ends_with(const char *s, const char *suffix)
{
    const char *a = s, *b = suffix;
    while (*a) a++;
    while (*b) b++;
    while (b > suffix) {
        if (a == s || *--a != *--b)
            return 0;
    }
    return 1;
}

static kernel_t find_kernel(const char *suffix)
{
    for (struct tgt_offload_entry *e = __start_omp_offloading_entries;
         e < __stop_omp_offloading_entries; e++)
        if (ends_with(e->name, suffix))
            return (kernel_t)e->addr;
    printf("[host] kernel not found: %s\n", suffix);
    return 0;
}

static void resolve_kernels(kernel_t *nop, kernel_t *map_to, kernel_t *map_tofrom)
{
    printf("[host] omp_offloading_entries table:\n");
    for (struct tgt_offload_entry *e = __start_omp_offloading_entries;
         e < __stop_omp_offloading_entries; e++) {
        printf("[host]   0x%08x %s\n", (uint32_t)(uintptr_t)e->addr, e->name);
    }
    *nop        = find_kernel(KERNEL_NOP_SUFFIX);
    *map_to     = find_kernel(KERNEL_MAP_TO_SUFFIX);
    *map_tofrom = find_kernel(KERNEL_MAP_TOFROM_SUFFIX);
}

// ===========================================================================
// PART 2 - what libomptarget + the HERO plugin do (host side)
// With UMA these L2 addresses are valid on the host too (see offload_layout.h).
// ===========================================================================
static volatile struct ring_buf *const h2a = (volatile struct ring_buf *)OFL_H2A_RING;
static volatile struct ring_buf *const a2h = (volatile struct ring_buf *)OFL_A2H_RING;

// Bump allocator, never frees.
// HERO: __tgt_rtl_data_alloc -> GOMP_OFFLOAD_alloc -> hero_dev_l2_malloc (o1heap).
static uintptr_t heap_next;
static uintptr_t data_alloc(uint32_t size)
{
    uintptr_t p = heap_next;
    heap_next += (size + 7u) & ~7u;
    return p;
}

// HERO: __tgt_rtl_data_submit -> GOMP_OFFLOAD_host2dev
static void data_submit(uintptr_t dev, const void *host, uint32_t size)
{
    for (uint32_t i = 0; i < size; i++)
        ((volatile uint8_t *)dev)[i] = ((const uint8_t *)host)[i];
}

// HERO: __tgt_rtl_data_retrieve -> GOMP_OFFLOAD_dev2host
static void data_retrieve(void *host, uintptr_t dev, uint32_t size)
{
    for (uint32_t i = 0; i < size; i++)
        ((uint8_t *)host)[i] = ((volatile uint8_t *)dev)[i];
}

// HERO: hero_dev_mbox_write (mailbox.c)
static void host_mbox_write(uint32_t w)
{
    while (rb_host_put(h2a, &w)) { }
}

// HERO: hero_dev_mbox_read (mailbox.c)
// TODO(RTEMS host): make it blocking with a timeout, the device runs in parallel.
static int host_mbox_read(uint32_t *w)
{
    return rb_host_get(a2h, w);       // 0 = read, -1 = empty
}

// Send part of __tgt_rtl_run_target_region (HERO rtl.cpp:457). HERO reuses a
// single dev_arg_buf; here each region has its own since everything is queued upfront.
static void run_region(void (*kernel)(uint64_t), uint32_t nargs, const uintptr_t *dev_ptrs)
{
    uint64_t *argbuf = (uint64_t *)data_alloc(8 * (nargs ? nargs : 1));
    for (uint32_t i = 0; i < nargs; i++)
        argbuf[i] = (uint64_t)dev_ptrs[i];

    host_mbox_write(MBOX_DEVICE_START);
    host_mbox_write((uint32_t)(uintptr_t)kernel);   // wrapper address
    host_mbox_write((uint32_t)(uintptr_t)argbuf);   // argument buffer address
    host_mbox_write(0);                             // miss handler count (unused)
}

// ---------------------------------------------------------------------------
// "Host program": the offload_benchmark regions, run once
// ---------------------------------------------------------------------------
static uint32_t tmp_1, tmp_2;            // host variables
static uintptr_t tofrom_p1, tofrom_p2;   // their L2 copies for the tofrom region
static kernel_t k_nop, k_map_to, k_map_tofrom;
static int kernels_missing;
#define N_REGIONS 4u

// TODO(RTEMS host): init is hero_dev_init / hero_dev_alloc_mboxes; the regions
// come from regions() in kernels_omp.c through libomptarget, which sends START
// and waits for DONE one region at a time.
void fake_host_before(void)
{
    // Invalidate the "ready" cell first: shared memory may survive between runs.
    *(volatile uint32_t *)OFL_READY_FLAG = 0;
    *(volatile uint32_t *)OFL_H2A_ADDR   = 0;
    *(volatile uint32_t *)OFL_A2H_ADDR   = 0;
    asm volatile("fence w,w" ::: "memory");

    heap_next = OFL_HEAP_BASE;

    // hero_dev_init: create the two mailboxes (mailbox.c: hero_dev_alloc_mboxes)
    rb_init(h2a, OFL_RING_SLOTS, sizeof(uint32_t));
    rb_init(a2h, OFL_RING_SLOTS, sizeof(uint32_t));
    h2a->prod.data_v = h2a->prod.data_p = OFL_H2A_DATA;   // virtual = physical with UMA
    a2h->prod.data_v = a2h->prod.data_p = OFL_A2H_DATA;

    resolve_kernels(&k_nop, &k_map_to, &k_map_tofrom);
    kernels_missing = !k_nop || !k_map_to || !k_map_tofrom;

    if (!kernels_missing) {
        // 1) #pragma omp target { nop }      ("enter_omp_init")
        run_region(k_nop, 0, 0);

        // 2) #pragma omp target { nop }      ("enter_omp_nop")
        run_region(k_nop, 0, 0);

        tmp_1 = 5;
        tmp_2 = 10;

        // 3) #pragma omp target map(to: tmp_1)
        {
            uintptr_t p1 = data_alloc(sizeof tmp_1);
            data_submit(p1, &tmp_1, sizeof tmp_1);
            run_region(k_map_to, 1, &p1);
        }

        // 4) #pragma omp target map(tofrom: tmp_1, tmp_2)
        {
            tofrom_p1 = data_alloc(sizeof tmp_1);
            tofrom_p2 = data_alloc(sizeof tmp_2);
            data_submit(tofrom_p1, &tmp_1, sizeof tmp_1);
            data_submit(tofrom_p2, &tmp_2, sizeof tmp_2);
            uintptr_t ptrs[2] = { tofrom_p1, tofrom_p2 };
            run_region(k_map_tofrom, 2, ptrs);
            // the "from" copy-back is done in fake_host_after
        }
    }

    // If a kernel is missing only STOP is sent: the device exits and the test fails.
    host_mbox_write(MBOX_DEVICE_STOP);

    // "Ready" cell: addresses first, flag LAST (same order and fences on the real host)
    *(volatile uint32_t *)OFL_H2A_ADDR = OFL_H2A_RING;
    *(volatile uint32_t *)OFL_A2H_ADDR = OFL_A2H_RING;
    asm volatile("fence w,w" ::: "memory");
    *(volatile uint32_t *)OFL_READY_FLAG = OFL_READY_MAGIC;
}

// TODO(RTEMS host): DONE is read inside __tgt_rtl_run_target_region (rtl.cpp:494-519)
// right after each START; libomptarget does the "from" copy-back after each region.
int fake_host_after(void)
{
    int errors = 0;
    uint32_t w, cycles;

    if (kernels_missing) {
        *(volatile uint32_t *)OFL_READY_FLAG = 0;
        printf("[host] TEST FAIL: missing kernels\n");
        return 1;
    }

    // One DONE reply per region (rtl.cpp:494-519)
    for (uint32_t r = 0; r < N_REGIONS; r++) {
        if (host_mbox_read(&w) || w != MBOX_DEVICE_DONE) {
            printf("[host] FAIL: missing DONE for region 0x%08x\n", r);
            return 1;
        }
        host_mbox_read(&cycles);
        for (uint32_t i = 2; i < MBOX_DONE_WORDS; i++)
            host_mbox_read(&w);                         // dma + 4 counters
        printf("[host] region 0x%08x DONE, kernel cycles = 0x%08x\n", r, cycles);
    }

    // "from" of the tofrom region: copy L2 -> host variables
    data_retrieve(&tmp_1, tofrom_p1, sizeof tmp_1);
    data_retrieve(&tmp_2, tofrom_p2, sizeof tmp_2);
    if (tmp_1 != tmp_2 || tmp_1 != 10) {
        printf("[host] FAIL: map tofrom, tmp_1 = 0x%08x\n", tmp_1);
        errors++;
    }

    *(volatile uint32_t *)OFL_READY_FLAG = 0;          // clean up for the next run

    printf(errors ? "[host] TEST FAIL\n" : "[host] TEST PASS\n");
    return errors;
}
